using System;
using System.Collections.Generic;
using DotThrow.Tests.Support;
using Xunit;
using static DotThrow.Tests.Support.Cases;

namespace DotThrow.Tests.Guards;

// Every collection shape that has its own overload (arrays, List, HashSet, Dictionary, the
// collection interfaces and lazy sequences), plus a type that uses the generic overload
// (Queue), against every count and item check: a pass, a fail and a null row each. The rows
// also run in collect mode, with an exception factory and on an inactive guard (AllCases).
public sealed class CollectionShapeGuardTests
{
    public static IEnumerable<CheckCase> FailureCases()
    {
        yield return Fail<int[]>(Array.Empty<int>(), (g, m) => g.IfNullOrEmpty(m), ErrorCodes.Empty, Expect.Argument, "'input' must not be empty.", label: "int[]: g.IfNullOrEmpty(m)");
        yield return Null<int[]>((g, m) => g.IfNullOrEmpty(m), label: "int[]: g.IfNullOrEmpty(m) on null");
        yield return Fail<int[]>(new[] { 1, 2, 3 }, (g, m) => g.IfCountEqualTo(3, m), ErrorCodes.CountEqualTo, Expect.Argument, "'input' must not have exactly 3 items.", label: "int[]: g.IfCountEqualTo(3, m)");
        yield return Null<int[]>((g, m) => g.IfCountEqualTo(3, m), label: "int[]: g.IfCountEqualTo(3, m) on null");
