        yield return Pass<Queue<int>>(new Queue<int>(new[] { 1, 2, 3 }), (g, m) => g.IfAny((int x) => x > 3, m), label: "Queue<int>: g.IfAny((int x) => x > 3, m)");
        yield return Pass<Queue<int>>(new Queue<int>(new[] { 1, 2, 3 }), (g, m) => g.IfNone((int x) => x > 2, m), label: "Queue<int>: g.IfNone((int x) => x > 2, m)");
        yield return Pass<Dictionary<int, string>>(new Dictionary<int, string> { [1] = "a", [2] = "b", [3] = "c" }, (g, m) => g.IfNullOrEmpty(m), label: "Dictionary<int, string>: g.IfNullOrEmpty(m)");
        yield return Pass<Dictionary<int, string>>(new Dictionary<int, string>(), (g, m) => g.IfCountEqualTo(3, m), label: "Dictionary<int, string>: g.IfCountEqualTo(3, m)");
        yield return Pass<Dictionary<int, string>>(new Dictionary<int, string> { [1] = "a", [2] = "b", [3] = "c" }, (g, m) => g.IfCountNotEqualTo(3, m), label: "Dictionary<int, string>: g.IfCountNotEqualTo(3, m)");
        yield return Pass<Dictionary<int, string>>(new Dictionary<int, string>(), (g, m) => g.IfCountGreaterThan(2, m), label: "Dictionary<int, string>: g.IfCountGreaterThan(2, m)");
        yield return Pass<Dictionary<int, string>>(new Dictionary<int, string> { [1] = "a", [2] = "b", [3] = "c" }, (g, m) => g.IfCountLessThan(1, m), label: "Dictionary<int, string>: g.IfCountLessThan(1, m)");
        yield return Pass<Dictionary<int, string>>(new Dictionary<int, string> { [1] = "a", [2] = "b", [3] = "c" }, (g, m) => g.IfCountOutOfRange(0, 3, m), label: "Dictionary<int, string>: g.IfCountOutOfRange(0, 3, m)");
        yield return Pass<string?[]>(new[] { "a", "b" }, (g, m) => g.IfContainsNull(m), label: "string?[]: g.IfContainsNull(m)");
        yield return Pass<List<string?>>(new List<string?> { "a", "b" }, (g, m) => g.IfContainsNull(m), label: "List<string?>: g.IfContainsNull(m)");
        yield return Pass<IEnumerable<string?>>(Sequences.Of<string?>("a", "b"), (g, m) => g.IfContainsNull(m), label: "IEnumerable<string?>: g.IfContainsNull(m)");
        yield return Pass<IList<string?>>(new[] { "a", "b" }, (g, m) => g.IfContainsNull(m), label: "IList<string?>: g.IfContainsNull(m)");
        yield return Pass<Queue<string?>>(new Queue<string?>(new[] { "a", "b" }), (g, m) => g.IfContainsNull(m), label: "Queue<string?>: g.IfContainsNull(m)");
        yield return Pass<int[]>(new[] { 0, 1 }, (g, m) => g.IfContainsNull(m), label: "int[]: value-type items are never null");
        yield return Pass<IEnumerable<int>>(Sequences.Of(0, 1), (g, m) => g.IfContainsNull(m), label: "IEnumerable<int>: value-type items are never null");
    }

    public static TheoryData<CheckCase> Failures => Data(FailureCases());

    public static TheoryData<CheckCase> Passes => Data(PassCases());

    [Theory]
    [MemberData(nameof(Failures))]
    public void Failing_check_throws_the_default_exception(CheckCase check) => check.AssertThrows();

    [Theory]
    [MemberData(nameof(Failures))]
    public void Failing_check_uses_a_custom_message(CheckCase check) => check.AssertCustomMessage();

    [Theory]
    [MemberData(nameof(Passes))]
    public void Passing_check_returns_the_value(CheckCase check) => check.AssertPasses();
}
